+  custom_items.push_back(TInt(1));
+  Any obj =
+      creator(Map<String, Any>({{"items", custom_items}, {"count", static_cast<int64_t>(5)}}));
+
+  auto* p = obj.as<TestObjWithFactory>();
+  ASSERT_NE(p, nullptr);
+  EXPECT_EQ(p->items.size(), 1);
+  EXPECT_EQ(p->count, 5);
+}
